const _blue=Color(0xFF1F5AA6);
const _docTypes={'nic_front':'NIC Front','nic_back':'NIC Back','police_report':'Police Report','grama_sevaka_report':'Grama Sevaka Report','education_certificate':'Education Certificate','cv':'CV','previous_employment_record':'Previous Employment Record'};
String _mime(String n){final s=n.toLowerCase();if(s.endsWith('.pdf'))return 'application/pdf';if(s.endsWith('.jpg')||s.endsWith('.jpeg'))return 'image/jpeg';if(s.endsWith('.png'))return 'image/png';if(s.endsWith('.webp'))return 'image/webp';if(s.endsWith('.mp4'))return 'video/mp4';if(s.endsWith('.mov'))return 'video/quicktime';if(s.endsWith('.pptx'))return 'application/vnd.openxmlformats-officedocument.presentationml.presentation';if(s.endsWith('.ppt'))return 'application/vnd.ms-powerpoint';if(s.endsWith('.xlsx'))return 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';if(s.endsWith('.xls'))return 'application/vnd.ms-excel';if(s.endsWith('.csv'))return 'text/csv';return 'application/octet-stream';}
void _toast(BuildContext c,String m){if(c.mounted)ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:Text(m)));}
Future<void> _open(BuildContext c,String url)async{if(!await launchUrl(Uri.parse(url),mode:LaunchMode.externalApplication))_toast(c,'Unable to open secure file.');}
class EmployeeIdDashboardScreen extends ConsumerWidget{
 const EmployeeIdDashboardScreen({super.key,required this.profile});final EmployeeProfile profile;
 @override Widget build(BuildContext c,WidgetRef r)=>Scaffold(appBar:AppBar(title:const Text('Company ID Dashboard'),actions:[IconButton(icon:const Icon(Icons.qr_code_scanner),onPressed:()=>Navigator.push(c,MaterialPageRoute<void>(builder:(_)=>QrScannerScreen(profile:profile))))]),floatingActionButton:profile.role==EmployeeRole.owner?FloatingActionButton.extended(onPressed:()=>_issue(c,r),icon:const Icon(Icons.add_card),label:const Text('Issue ID')):null,body:r.watch(employeeCardsProvider).when(loading:()=>const Center(child:CircularProgressIndicator()),error:(e,_)=>Center(child:Text(e.toString())),data:(items)=>items.isEmpty?const Center(child:Text('No employee ID cards issued.')):ListView(children:items.map((x)=>Card(child:ListTile(leading:const Icon(Icons.badge,color:_blue),title:Text(x.title),subtitle:Text('Employee record: '+x.data['employee_id'].toString()+' · '+x.status.toUpperCase()))).toList())));
 Future<void> _issue(BuildContext c,WidgetRef r)async{try{final people=await r.read(employeeOptionsProvider.future);if(people.isEmpty)return;String id=people.first.id;final chosen=await showDialog<String>(context:c,builder:(ctx)=>StatefulBuilder(builder:(ctx,set)=>AlertDialog(title:const Text('Issue employee ID'),content:DropdownButtonFormField<String>(value:id,isExpanded:true,items:people.map((p)=>DropdownMenuItem(value:p.id,child:Text(p.name+' · '+p.code))).toList(),onChanged:(v)=>set(()=>id=v??id)),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(ctx,id),child:const Text('Issue'))])));if(chosen==null)return;final issued=await r.read(lifecycleServiceProvider).issueId(chosen);r.invalidate(employeeCardsProvider);if(!c.mounted)return;await showDialog<void>(context:c,builder:(ctx)=>AlertDialog(title:const Text('Digital ID issued'),content:Column(mainAxisSize:MainAxisSize.min,children:[const Text('Give this QR to the employee now. Reissue replaces the previous QR token.'),QrImageView(data:'DDWC:'+issued['qr_token'].toString(),size:190),Text(issued['card_number'].toString())]),actions:[FilledButton(onPressed:()=>Navigator.pop(ctx),child:const Text('Done'))]));}catch(e){_toast(c,'ID issue failed: '+e.toString());}}
}
class QrScannerScreen extends ConsumerStatefulWidget{const QrScannerScreen({super.key,required this.profile});final EmployeeProfile profile;@override ConsumerState<QrScannerScreen> createState()=>_QrScannerState();}
class _QrScannerState extends ConsumerState<QrScannerScreen>{bool busy=false;Map<String,dynamic>? result;String? error;@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('QR Scanner')),body:Column(children:[Expanded(child:MobileScanner(onDetect:(capture)async{if(busy||capture.barcodes.isEmpty)return;final raw=capture.barcodes.first.rawValue;if(raw==null)return;setState(()=>busy=true);try{final token=raw.startsWith('DDWC:')?raw.substring(5):raw;final v=await ref.read(lifecycleServiceProvider).verifyQr(token);if(mounted)setState(()=>result=v);}catch(e){if(mounted)setState(()=>error=e.toString());}finally{if(mounted)setState(()=>busy=false);}})),if(busy)const LinearProgressIndicator(),if(error!=null)Text(error!,style:const TextStyle(color:Colors.red)),if(result!=null)Expanded(child:QrVerificationScreen(result:result!)),if(result==null)const Padding(padding:EdgeInsets.all(16),child:Text('Scan an active DD WORLD employee QR code.'))]));}
class QrVerificationScreen extends StatelessWidget{const QrVerificationScreen({super.key,required this.result});final Map<String,dynamic> result;@override Widget build(BuildContext c){final ok=result['verified']==true;Widget row(String k)=>ListTile(dense:true,title:Text(k.replaceAll('_',' ').toUpperCase()),subtitle:Text(result[k]?.toString()??'—'));return Card(child:Column(children:[ListTile(leading:Icon(ok?Icons.verified:Icons.gpp_bad,color:ok?Colors.green:Colors.red),title:Text(ok?'EMPLOYEE VERIFIED':'NOT VALID')),row('employee_name'),row('staff_code'),row('team_name'),row('employee_position'),row('status')]));}}
class DocumentVaultScreen extends ConsumerWidget{
 const DocumentVaultScreen({super.key,required this.profile});final EmployeeProfile profile;
 @override Widget build(BuildContext c,WidgetRef r)=>Scaffold(appBar:AppBar(title:const Text('Employee Document Vault')),floatingActionButton:FloatingActionButton.extended(onPressed:()=>_upload(c,r),icon:const Icon(Icons.upload_file),label:const Text('Upload')),body:r.watch(employeeDocumentsProvider).when(loading:()=>const Center(child:CircularProgressIndicator()),error:(e,_)=>Center(child:Text(e.toString())),data:(items)=>items.isEmpty?const Center(child:Text('No documents submitted.')):ListView(children:items.map((x)=>Card(child:ListTile(title:Text(_docTypes[x.data['document_type']]??x.data['document_type'].toString()),subtitle:Text(x.data['file_name'].toString()+' · '+x.status.toUpperCase()),trailing:profile.role==EmployeeRole.owner&&x.status=='pending'?PopupMenuButton<String>(onSelected:(v)=>_review(c,r,x,v=='approve'),itemBuilder:(_)=>const [PopupMenuItem(value:'approve',child:Text('Approve')),PopupMenuItem(value:'reject',child:Text('Reject'))]):const Icon(Icons.open_in_new),onTap:()=>_openDoc(c,r,x))).toList())));
 Future<void> _upload(BuildContext c,WidgetRef r)async{String type='nic_front';final t=await showDialog<String>(context:c,builder:(ctx)=>StatefulBuilder(builder:(ctx,set)=>AlertDialog(title:const Text('Document type'),content:DropdownButtonFormField<String>(value:type,items:_docTypes.entries.map((e)=>DropdownMenuItem(value:e.key,child:Text(e.value))).toList(),onChanged:(v)=>set(()=>type=v??type)),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(ctx,type),child:const Text('Choose file'))])));if(t==null)return;final f=await FilePicker.platform.pickFiles(type:FileType.custom,allowedExtensions:const ['pdf','jpg','jpeg','png','webp'],withData:true);if(f?.files.single.bytes==null)return;try{await r.read(lifecycleServiceProvider).uploadDocument(t,f!.files.single.name,f.files.single.bytes!,_mime(f.files.single.name));r.invalidate(employeeDocumentsProvider);_toast(c,'Document submitted for Owner verification.');}catch(e){_toast(c,e.toString());}}
 Future<void> _openDoc(BuildContext c,WidgetRef r,LifecycleRow x)async{try{await _open(c,await r.read(lifecycleServiceProvider).documentUrl(x.data['file_path'].toString()));}catch(e){_toast(c,e.toString());}}
 Future<void> _review(BuildContext c,WidgetRef r,LifecycleRow x,bool approve)async{final note=TextEditingController();final ok=await showDialog<bool>(context:c,builder:(ctx)=>AlertDialog(title:Text(approve?'Approve document':'Reject document'),content:TextField(controller:note,decoration:const InputDecoration(labelText:'Review note')),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(ctx,true),child:const Text('Confirm'))]));if(ok==true){try{await r.read(lifecycleServiceProvider).reviewDocument(x.id,approve,note.text);r.invalidate(employeeDocumentsProvider);_toast(c,'Document decision saved.');}catch(e){_toast(c,e.toString());}}note.dispose();}
}
class LeaveManagementScreen extends ConsumerWidget{
 const LeaveManagementScreen({super.key,required this.profile});final EmployeeProfile profile;
 @override Widget build(BuildContext c,WidgetRef r)=>Scaffold(appBar:AppBar(title:const Text('Leave Management')),floatingActionButton:FloatingActionButton.extended(onPressed:()=>_apply(c,r),icon:const Icon(Icons.add),label:const Text('Apply Leave')),body:r.watch(leaveRequestsProvider).when(loading:()=>const Center(child:CircularProgressIndicator()),error:(e,_)=>Center(child:Text(e.toString())),data:(items)=>items.isEmpty?const Center(child:Text('No leave requests.')):ListView(children:items.map((x){final stage=x.data['review_stage']?.toString();final can=(profile.role==EmployeeRole.teamLeader&&stage=='PENDING_TEAM_LEADER')||(profile.role==EmployeeRole.owner&&stage=='PENDING_OWNER');return Card(child:ListTile(title:Text(x.data['leave_type'].toString().toUpperCase()),subtitle:Text(x.data['start_date'].toString()+' to '+x.data['end_date'].toString()+' · '+x.status+'\\n'+x.data['reason'].toString()),isThreeLine:true,trailing:can?PopupMenuButton<String>(onSelected:(v)=>_review(c,r,x,v=='approve'),itemBuilder:(_)=>const [PopupMenuItem(value:'approve',child:Text('Approve')),PopupMenuItem(value:'reject',child:Text('Reject'))]):Chip(label:Text(x.status)));}).toList())));
 Future<void> _apply(BuildContext c,WidgetRef r)async{String type='annual',half='morning';DateTime start=DateTime.now(),end=DateTime.now();final reason=TextEditingController();final ok=await showDialog<bool>(context:c,builder:(ctx)=>StatefulBuilder(builder:(ctx,set)=>AlertDialog(title:const Text('Apply leave'),content:Column(mainAxisSize:MainAxisSize.min,children:[DropdownButtonFormField<String>(value:type,items:const [DropdownMenuItem(value:'annual',child:Text('Annual Leave')),DropdownMenuItem(value:'casual',child:Text('Casual Leave')),DropdownMenuItem(value:'sick',child:Text('Sick Leave')),DropdownMenuItem(value:'half_day',child:Text('Half Day'))],onChanged:(v)=>set(()=>type=v??type)),if(type=='half_day')DropdownButtonFormField<String>(value:half,items:const [DropdownMenuItem(value:'morning',child:Text('Morning')),DropdownMenuItem(value:'afternoon',child:Text('Afternoon'))],onChanged:(v)=>set(()=>half=v??half)),ListTile(title:const Text('Start'),subtitle:Text(start.toString().substring(0,10)),onTap:()async{final d=await showDatePicker(context:ctx,initialDate:start,firstDate:DateTime.now().subtract(const Duration(days:365)),lastDate:DateTime.now().add(const Duration(days:730)));if(d!=null)set(()=>start=d);}),ListTile(title:const Text('End'),subtitle:Text(end.toString().substring(0,10)),onTap:()async{final d=await showDatePicker(context:ctx,initialDate:end.isBefore(start)?start:end,firstDate:start,lastDate:DateTime.now().add(const Duration(days:730)));if(d!=null)set(()=>end=d);}),TextField(controller:reason,decoration:const InputDecoration(labelText:'Reason'))]),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(ctx,true),child:const Text('Submit'))]));if(ok==true){try{await r.read(lifecycleServiceProvider).applyLeave(type,start,end,reason.text,half);r.invalidate(leaveRequestsProvider);_toast(c,'Leave request submitted.');}catch(e){_toast(c,e.toString());}}reason.dispose();}
 Future<void> _review(BuildContext c,WidgetRef r,LifecycleRow x,bool approve)async{final note=TextEditingController();try{await r.read(lifecycleServiceProvider).reviewLeave(x.id,approve,note.text);r.invalidate(leaveRequestsProvider);}catch(e){_toast(c,e.toString());}finally{note.dispose();}}
}
class DownloadCenterScreen extends ConsumerWidget{
 const DownloadCenterScreen({super.key,required this.profile});final EmployeeProfile profile;
 @override Widget build(BuildContext c,WidgetRef r)=>Scaffold(appBar:AppBar(title:const Text('Download Center')),floatingActionButton:profile.role==EmployeeRole.owner?FloatingActionButton.extended(onPressed:()=>_upload(c,r),icon:const Icon(Icons.upload_file),label:const Text('Publish')):null,body:r.watch(downloadsProvider).when(loading:()=>const Center(child:CircularProgressIndicator()),error:(e,_)=>Center(child:Text(e.toString())),data:(items)=>ListView(children:items.where((x)=>x.data['is_published']==true).map((x)=>Card(child:ListTile(title:Text(x.title),subtitle:Text(x.data['file_name'].toString()),trailing:const Icon(Icons.download),onTap:()async{try{await _open(c,await r.read(lifecycleServiceProvider).openDownload(x));}catch(e){_toast(c,e.toString());}}))).toList())));
 Future<void> _upload(BuildContext c,WidgetRef r)async{final title=TextEditingController(),desc=TextEditingController();String cat='pdf_report';final v=await showDialog<String>(context:c,builder:(ctx)=>StatefulBuilder(builder:(ctx,set)=>AlertDialog(title:const Text('Publish download'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:title,decoration:const InputDecoration(labelText:'Title')),TextField(controller:desc,decoration:const InputDecoration(labelText:'Description')),DropdownButtonFormField<String>(value:cat,items:const [DropdownMenuItem(value:'pdf_report',child:Text('PDF Report')),DropdownMenuItem(value:'excel_report',child:Text('Excel Report')),DropdownMenuItem(value:'training_file',child:Text('Training File')),DropdownMenuItem(value:'company_file',child:Text('Company File'))],onChanged:(x)=>set(()=>cat=x??cat))]),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(ctx,cat),child:const Text('Choose file'))])));if(v==null)return;final f=await FilePicker.platform.pickFiles(withData:true);if(f?.files.single.bytes==null)return;try{final x=f!.files.single;await r.read(lifecycleServiceProvider).uploadFile('downloads','dd-downloads',title.text,desc.text,v,x.name,x.bytes!,_mime(x.name));r.invalidate(downloadsProvider);_toast(c,'File published.');}catch(e){_toast(c,e.toString());}finally{title.dispose();desc.dispose();}}
}
class TrainingCenterScreen extends ConsumerWidget{
 const TrainingCenterScreen({super.key,required this.profile});final EmployeeProfile profile;
 @override Widget build(BuildContext c,WidgetRef r)=>DefaultTabController(length:3,child:Scaffold(appBar:AppBar(title:const Text('Training Center'),bottom:const TabBar(tabs:[Tab(text:'All'),Tab(text:'Sayuru'),Tab(text:'Govi Mithuru')])),floatingActionButton:profile.role==EmployeeRole.owner?FloatingActionButton.extended(onPressed:()=>_upload(c,r),icon:const Icon(Icons.add),label:const Text('Add training')):null,body:const TabBarView(children:[_TrainingList(null),_TrainingList('sayuru'),_TrainingList('govimithuru')])));
 Future<void> _upload(BuildContext c,WidgetRef r)async{final title=TextEditingController(),desc=TextEditingController();String product='sayuru',type='video';final form=await showDialog<Map<String,String>>(context:c,builder:(ctx)=>StatefulBuilder(builder:(ctx,set)=>AlertDialog(title:const Text('Add training'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:title,decoration:const InputDecoration(labelText:'Title')),TextField(controller:desc,decoration:const InputDecoration(labelText:'Description')),DropdownButtonFormField<String>(value:product,items:const [DropdownMenuItem(value:'sayuru',child:Text('Sayuru')),DropdownMenuItem(value:'govimithuru',child:Text('Govi Mithuru')),DropdownMenuItem(value:'general',child:Text('General'))],onChanged:(v)=>set(()=>product=v??product)),DropdownButtonFormField<String>(value:type,items:const [DropdownMenuItem(value:'video',child:Text('Video')),DropdownMenuItem(value:'pdf',child:Text('PDF')),DropdownMenuItem(value:'presentation',child:Text('Presentation'))],onChanged:(v)=>set(()=>type=v??type))]),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(ctx,{'product':product,'type':type}),child:const Text('Choose file'))])));if(form==null)return;final ext=form['type']=='video'?['mp4','mov']:form['type']=='pdf'?['pdf']:['ppt','pptx'];final f=await FilePicker.platform.pickFiles(type:FileType.custom,allowedExtensions:ext,withData:true);if(f?.files.single.bytes==null)return;try{final x=f!.files.single;await r.read(lifecycleServiceProvider).uploadFile('training_materials','dd-training-materials',title.text,desc.text,form['product']!+'|'+form['type']!,x.name,x.bytes!,_mime(x.name));r.invalidate(trainingProvider(null));r.invalidate(trainingProvider('sayuru'));r.invalidate(trainingProvider('govimithuru'));_toast(c,'Training material published.');}catch(e){_toast(c,e.toString());}finally{title.dispose();desc.dispose();}}
}
class _TrainingList extends ConsumerWidget{const _TrainingList(this.product);final String? product;@override Widget build(BuildContext c,WidgetRef r)=>r.watch(trainingProvider(product)).when(loading:()=>const Center(child:CircularProgressIndicator()),error:(e,_)=>Center(child:Text(e.toString())),data:(items)=>ListView(children:items.map((x)=>Card(child:ListTile(title:Text(x.title),subtitle:Text(x.data['file_name'].toString()),leading:const Icon(Icons.school,color:_blue),onTap:()async{try{await _open(c,await r.read(lifecycleServiceProvider).openTraining(x));}catch(e){_toast(c,e.toString());}},onLongPress:()async{try{await r.read(lifecycleServiceProvider).completeTraining(x.id);_toast(c,'Training marked complete.');}catch(e){_toast(c,e.toString());}}))).toList()));}
}
